#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
مولّد مكتبة الأصوات البشرية المسبقة لمتجر معاذ (ترقية 5x للأساسية و 10x لـ VIP)
- 9 شخصيات VIP × 150 سيناريو (10 أضعاف السيناريوهات الأساسية) = 1,350 سيناريو.
- 9 شخصيات أساسية × 75 سيناريو (5 أضعاف السيناريوهات الأساسية) = 675 سيناريو.
- يضغط الصوت إلى MP3 أحادي (Mono 48kbps) مع توحيد مستوى الصوت (loudnorm) عبر ffmpeg
  مع رجوع آمن إلى WAV عند غياب ffmpeg.
- يحفظ في sounds_gemini_manifest.json حقول text و file و mood و durationMs و tier.
- يدعم تدوير المفاتيح ويتوقف فوراً عند استنفاد الحصة (429).
- معزول تماماً عن الدفع وشام كاش والإيصالات المالية.
"""

import base64
import json
import os
import shutil
import struct
import subprocess
import time
import urllib.error
import urllib.request

OUT_DIR = "sounds_gemini"
MANIFEST_PATH = "sounds_gemini_manifest.json"
MAX_CLIPS_PER_RUN = int(os.environ.get("MAX_CLIPS_PER_RUN", "20"))
DELAY_BETWEEN_CALLS = float(os.environ.get("DELAY_BETWEEN_CALLS", "4.5"))
TTS_MODEL = os.environ.get("GEMINI_TTS_MODEL", "gemini-2.5-flash-preview-tts")

API_KEYS = []
for env_name in ["GEMINI_API_KEY", "GEMINI_API_KEY_1", "GEMINI_API_KEY_2", "GEMINI_API_KEY_3", "GEMINI_API_KEY_4"]:
    val = os.environ.get(env_name, "").strip()
    if val and val not in API_KEYS:
        API_KEYS.append(val)

