def pcm_to_wav(pcm_bytes: bytes, sample_rate: int = 24000) -> bytes:
    header = bytearray(44)
    pcm_len = len(pcm_bytes)
    header[0:4] = b"RIFF"
    struct.pack_into("<I", header, 4, 36 + pcm_len)
    header[8:12] = b"WAVE"
    header[12:16] = b"fmt "
    struct.pack_into("<I", header, 16, 16)
    struct.pack_into("<H", header, 20, 1)
    struct.pack_into("<H", header, 22, 1)
    struct.pack_into("<I", header, 24, sample_rate)
    struct.pack_into("<I", header, 28, sample_rate * 2)
    struct.pack_into("<H", header, 32, 2)
    struct.pack_into("<H", header, 34, 16)
    header[36:40] = b"data"
    struct.pack_into("<I", header, 40, pcm_len)
    return bytes(header) + pcm_bytes


def encode_and_normalize_audio(pcm_bytes: bytes, sample_rate: int, out_base_no_ext: str):
    """يحوّل PCM إلى MP3 أحادي 48kbps مع توحيد مستوى الصوت (loudnorm)، أو يعود إلى WAV."""
    wav_bytes = pcm_to_wav(pcm_bytes, sample_rate)
    duration_ms = max(800, int((len(pcm_bytes) / max(1, sample_rate * 2)) * 1000))

    if shutil.which("ffmpeg"):
        tmp_wav = out_base_no_ext + ".tmp.wav"
        out_mp3 = out_base_no_ext + ".mp3"
        try:
            with open(tmp_wav, "wb") as f:
                f.write(wav_bytes)
            subprocess.run(
                [
                    "ffmpeg", "-y", "-i", tmp_wav,
                    "-ac", "1",
                    "-af", "loudnorm=I=-16:TP=-1.5:LRA=11",
                    "-codec:a", "libmp3lame",
                    "-b:a", "48k",
                    out_mp3
                ],
                check=True,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL
            )
            if os.path.exists(out_mp3) and os.path.getsize(out_mp3) > 400:
                return out_mp3, duration_ms
        except Exception:
            pass
        finally:
            if os.path.exists(tmp_wav):
                try:
                    os.remove(tmp_wav)
                except Exception:
                    pass

    out_wav = out_base_no_ext + ".wav"
    with open(out_wav, "wb") as f:
        f.write(wav_bytes)
    return out_wav, duration_ms


def call_gemini_tts(api_key: str, text: str, voice_name: str, style_hint: str):
    url = f"https://generativelanguage.googleapis.com/v1beta/models/{TTS_MODEL}:generateContent?key={api_key}"
    prompt_text = f"{style_hint}. اقرأ الجملة التالية بصوت بشري طبيعي 100% دون أي إضافات: {text}"
    payload = {
        "contents": [{"parts": [{"text": prompt_text}]}],
        "generationConfig": {
            "responseModalities": ["AUDIO"],
            "speechConfig": {
                "voiceConfig": {
                    "prebuiltVoiceConfig": {"voiceName": voice_name}
                }
            }
        }
    }
    req = urllib.request.Request(
        url,
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=45) as resp:
            data = json.loads(resp.read().decode("utf-8"))
        parts = data.get("candidates", [{}])[0].get("content", {}).get("parts", [])
        for part in parts:
            inline = part.get("inlineData") or {}
            b64 = inline.get("data")
            mime = inline.get("mimeType", "")
            if b64:
                raw = base64.b64decode(b64)
                rate = 24000
                if "rate=" in mime.lower():
                    try:
                        rate = int(mime.lower().split("rate=")[1].split(";")[0].strip())
                    except Exception:
                        rate = 24000
                return raw, rate, None
        return None, 24000, "NO_AUDIO_IN_RESPONSE"
    except urllib.error.HTTPError as e:
        return None, 24000, f"HTTP_{e.code}"
    except Exception as e:
        return None, 24000, str(e)


def find_existing_clip(base_no_ext: str):
    for ext in (".mp3", ".wav"):
        p = base_no_ext + ext
        if os.path.exists(p) and os.path.getsize(p) > 400:
            return p
    return None


def main():
    os.makedirs(OUT_DIR, exist_ok=True)
    if not API_KEYS:
        print("⚠️ No GEMINI_API_KEY found in environment secrets. Skipping generation.")
        return

    manifest = {
        "version": "5.0-vip10x-std5x",
        "updatedAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "personas": {}
    }

    generated_now = 0
    skipped_existing = 0
    key_idx = 0
    quota_exhausted = False

    # VIP personas first so they always take top priority in generation runs
    ordered_pids = sorted(
        PERSONA_VOICE_LIBRARY.keys(),
        key=lambda k: (0 if PERSONA_VOICE_LIBRARY[k].get("tier") == "vip" else 1, k)
    )

    for pid in ordered_pids:
        cfg = PERSONA_VOICE_LIBRARY[pid]
        manifest["personas"][pid] = {}
        for idx, (intent, mood, text) in enumerate(cfg["scenarios"], start=1):
            base_no_ext = os.path.join(OUT_DIR, f"{pid}_{intent}_{idx}").replace("\\", "/")
            existing_file = find_existing_clip(base_no_ext)

            if existing_file:
                skipped_existing += 1
                manifest["personas"][pid].setdefault(intent, []).append({
                    "text": text,
                    "file": existing_file,
                    "mood": mood,
                    "tier": cfg.get("tier", "standard")
                })
                continue

            if generated_now >= MAX_CLIPS_PER_RUN or quota_exhausted:
                continue

            success = False
            hit_429_count = 0
            for _ in range(len(API_KEYS)):
                current_key = API_KEYS[key_idx % len(API_KEYS)]
                key_idx += 1
                pcm_bytes, sample_rate, err = call_gemini_tts(current_key, text, cfg["voice"], cfg["hint"])
                if pcm_bytes and len(pcm_bytes) > 600:
                    saved_path, dur_ms = encode_and_normalize_audio(pcm_bytes, sample_rate, base_no_ext)
                    manifest["personas"][pid].setdefault(intent, []).append({
                        "text": text,
                        "file": saved_path,
                        "mood": mood,
                        "durationMs": dur_ms,
                        "tier": cfg.get("tier", "standard")
                    })
                    generated_now += 1
                    success = True
                    print(f"[OK] {saved_path} ({os.path.getsize(saved_path)} bytes, {dur_ms}ms)")
                    break
                else:
                    print(f"[WARN] {base_no_ext} failed with key #{key_idx}: {err}")
                    if err == "HTTP_429":
                        hit_429_count += 1
                        continue
                    break

            if not success:
                print(f"[STOP] Quota or error reached on {base_no_ext}")
                if hit_429_count >= len(API_KEYS):
                    quota_exhausted = True
                    print("[COOLDOWN] All keys returned HTTP_429. Stopping new API calls safely.")
                    continue

            time.sleep(DELAY_BETWEEN_CALLS)

    with open(MANIFEST_PATH, "w", encoding="utf-8") as f:
        json.dump(manifest, f, ensure_ascii=False, indent=2)

    print(f"Summary: Generated={generated_now} | Existing={skipped_existing} | Keys={len(API_KEYS)}")


if __name__ == "__main__":
    main()
